 document.querySelectorAll<HTMLButtonElement>('[data-copy]').forEach(b=>b.onclick=()=>{if(mode==='example'){toast('Example invoice. Create an onchain invoice to share a real checkout.');return;}const u=new URL(location.origin);u.searchParams.set('account',account!);u.searchParams.set('invoice',b.dataset.copy!);if(local)u.searchParams.set('local','1');void navigator.clipboard.writeText(u.href).then(()=>toast('Checkout link copied.'),()=>toast('Clipboard access was denied.'));});
